class Coffee extends DataClass implements Insertable<Coffee> {
  final String id;
  final String name;
  final String roaster;
  final String? notes;
  final int? paidPriceCents;
  final double? rating;
  final String? roastLevel;

  /// Comma-separated tasting notes, e.g. "Nectarine, jasmine".
  final String? flavorProfile;
  final bool isFavorite;
  final bool isDecaf;

  /// Web page of the coffee in the roaster's shop.
  final String? shopUrl;

  /// Rest the roaster recommends before brewing, in days after roasting.
  final int? restDays;
  final int createdAtMs;
  final int updatedAtMs;
  final int? archivedAtMs;
  const Coffee({
    required this.id,
    required this.name,
    required this.roaster,
    this.notes,
    this.paidPriceCents,
    this.rating,
    this.roastLevel,
    this.flavorProfile,
    required this.isFavorite,
    required this.isDecaf,
