class FrozenPortion extends DataClass implements Insertable<FrozenPortion> {
  final String id;
  final String lotId;

  /// Short code to write on the container, unique across portions.
  final String label;
  final String? container;

  /// Local calendar date (ISO `yyyy-MM-dd`) when the coffee was frozen.
  final String frozenDate;
  final double initialGrams;
  final double remainingGrams;
  final String? notes;
  final int createdAtMs;
  final int updatedAtMs;

  /// Set when the last grams are thawed.
  final int? thawedAtMs;
  const FrozenPortion({
    required this.id,
    required this.lotId,
    required this.label,
    this.container,
    required this.frozenDate,
    required this.initialGrams,
    required this.remainingGrams,
    this.notes,
