    map['label'] = Variable<String>(label);
    if (!nullToAbsent || container != null) {
      map['container'] = Variable<String>(container);
    }
    map['frozen_date'] = Variable<String>(frozenDate);
    map['initial_grams'] = Variable<double>(initialGrams);
    map['remaining_grams'] = Variable<double>(remainingGrams);
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['created_at_ms'] = Variable<int>(createdAtMs);
    map['updated_at_ms'] = Variable<int>(updatedAtMs);
    if (!nullToAbsent || thawedAtMs != null) {
      map['thawed_at_ms'] = Variable<int>(thawedAtMs);
    }
    return map;
  }

