    return FrozenPortionsCompanion(
      id: Value(id),
      lotId: Value(lotId),
      label: Value(label),
      container: container == null && nullToAbsent
          ? const Value.absent()
          : Value(container),
      frozenDate: Value(frozenDate),
      initialGrams: Value(initialGrams),
      remainingGrams: Value(remainingGrams),
      notes: notes == null && nullToAbsent
          ? const Value.absent()
          : Value(notes),
      createdAtMs: Value(createdAtMs),
