class WaterProfile extends DataClass implements Insertable<WaterProfile> {
  final String id;
  final String name;
  final double? ghPpmAsCaCO3;
  final double? khPpmAsCaCO3;
  final double? tdsPpm;
  final double? ph;

  /// Dissolved minerals in ppm (mg/l) of the ion itself.
  final double? calciumPpm;
  final double? magnesiumPpm;
  final double? sodiumPpm;
  final double? potassiumPpm;
  final double? chloridePpm;
  final double? sulfatePpm;
  final double? bicarbonatePpm;
