      map['kh_ppm_as_caco3'] = Variable<double>(khPpmAsCaCO3);
    }
    if (!nullToAbsent || tdsPpm != null) {
      map['tds_ppm'] = Variable<double>(tdsPpm);
    }
    if (!nullToAbsent || ph != null) {
      map['ph'] = Variable<double>(ph);
    }
    if (!nullToAbsent || calciumPpm != null) {
      map['calcium_ppm'] = Variable<double>(calciumPpm);
    }
    if (!nullToAbsent || magnesiumPpm != null) {
      map['magnesium_ppm'] = Variable<double>(magnesiumPpm);
    }
    if (!nullToAbsent || sodiumPpm != null) {
      map['sodium_ppm'] = Variable<double>(sodiumPpm);
    }
    if (!nullToAbsent || potassiumPpm != null) {
      map['potassium_ppm'] = Variable<double>(potassiumPpm);
    }
    if (!nullToAbsent || chloridePpm != null) {
      map['chloride_ppm'] = Variable<double>(chloridePpm);
    }
    if (!nullToAbsent || sulfatePpm != null) {
      map['sulfate_ppm'] = Variable<double>(sulfatePpm);
    }
    if (!nullToAbsent || bicarbonatePpm != null) {
