    }
    if (!nullToAbsent || recipeJson != null) {
      map['recipe_json'] = Variable<String>(recipeJson);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    if (!nullToAbsent || archivedAtMs != null) {
      map['archived_at_ms'] = Variable<int>(archivedAtMs);
    }
    return map;
  }

  WaterProfilesCompanion toCompanion(bool nullToAbsent) {
    return WaterProfilesCompanion(
      id: Value(id),
      name: Value(name),
      ghPpmAsCaCO3: ghPpmAsCaCO3 == null && nullToAbsent
