  WaterProfile copyWith({
    String? id,
    String? name,
    Value<double?> ghPpmAsCaCO3 = const Value.absent(),
    Value<double?> khPpmAsCaCO3 = const Value.absent(),
    Value<double?> tdsPpm = const Value.absent(),
    Value<double?> ph = const Value.absent(),
    Value<double?> calciumPpm = const Value.absent(),
