class Brew extends DataClass implements Insertable<Brew> {
  final String id;
  final String coffeeId;
  final String? lotId;
  final String? methodId;
  final String? grinderId;
  final String? waterProfileId;
  final String? waterProfileName;
  final bool isPreGround;
  final String methodName;
  final String? grinderName;
  final String? grindSetting;
  final double? doseGrams;

  /// The original frozen portion, when the app recorded the thaw for this brew.
  final String? frozenPortionId;

  /// Part of the dose taken from that portion; the rest used available coffee.
  final double? frozenDoseGrams;
  final double? waterGrams;
  final double? beverageGrams;
  final String? recipientId;
  final String? recipientName;
  final double? recipientGrams;
  final int? timeSeconds;
  final double? temperatureC;
  final double? brix;
  final double? brixFactor;
  final int? feederRpm;
  final double? tdsPercent;

  /// Grinder speed; only kept when the grinder has adjustable RPM.
  final int? grindRpm;

  /// Peak espresso extraction pressure in bar.
  final double? pressureBar;

  /// Espresso pre-infusion or filter bloom length.
  final int? preinfusionSeconds;
  final int? bloomSeconds;

  /// Recorded filter pours; null means unrecorded, unlike an explicit zero.
  final int? bloomCount;
  final int? pourCount;
  final String? pourPhasesJson;

  /// Espresso: seconds until the first drop reaches the cup.
  final int? firstDripSeconds;

  /// Extraction compass: -1 sour, 0 balanced, 1 bitter.
  final int? tasteBalance;

  /// Extraction compass: -1 weak, 0 balanced, 1 strong.
  final int? tasteStrength;

  /// Flavour scores from 0 to 5.
  final int? acidity;
  final int? sweetness;
  final int? bitterness;
  final int? body;
  final int? aftertaste;

  /// Machine profile or recipe name, e.g. a Meticulous profile.
  final String? profileName;
  final double? rating;

  /// The recipe a new brew of the same coffee and method starts from; at
  /// most one per coffee and method.
  final bool isFavorite;
  final String? notes;
  final int brewedAtMs;
  final int createdAtMs;
  final int updatedAtMs;
  final int? archivedAtMs;
  final bool? archivedByCoffee;
  final bool? stockReviewPending;
